// Typed fetch client. Every request/response type below is imported
// from `./schema.ts`, generated by `npm run generate:types` from the
// FastAPI app's own OpenAPI schema (see scripts/generate-openapi.sh) —
// nothing here is a hand-duplicated shape, so the dashboard can't drift
// from what the backend (and therefore the CLI, which shares the same
// `assess`/`cluster` functions) actually validates.
import type { components } from "./schema";

export type CampaignSummary = components["schemas"]["CampaignSummary"];
export type CampaignListResponse = components["schemas"]["CampaignListResponse"];
export type CampaignDetail = components["schemas"]["CampaignDetail"];
export type CampaignMemberOut = components["schemas"]["CampaignMemberOut"];
export type CampaignEventOut = components["schemas"]["CampaignEventOut"];
export type AssessmentStatusOut = components["schemas"]["AssessmentStatusOut"];
export type CampaignGraph = components["schemas"]["CampaignGraph"];
export type GraphNode = components["schemas"]["GraphNode"];
export type GraphEdge = components["schemas"]["GraphEdge"];
export type ExplainOut = components["schemas"]["ExplainOut"];
export type DirectEdgeOut = components["schemas"]["DirectEdgeOut"];
export type AssessmentOut = components["schemas"]["AssessmentOut"];
export type AssessmentDraft = components["schemas"]["AssessmentDraft"];
export type KeyJudgement = components["schemas"]["KeyJudgement"];
export type Targeting = components["schemas"]["Targeting"];
export type Ttp = components["schemas"]["Ttp"];
export type Financial = components["schemas"]["Financial"];
export type Attribution = components["schemas"]["Attribution"];
export type AssessmentVersionSummary = components["schemas"]["AssessmentVersionSummary"];
export type AssessmentDiffOut = components["schemas"]["AssessmentDiffOut"];
export type AttackTechniquesOut = components["schemas"]["AttackTechniquesOut"];
export type AttackTechniqueOut = components["schemas"]["AttackTechniqueOut"];
export type ReportMeta = components["schemas"]["ReportMeta"];
export type FeedIndexOut = components["schemas"]["FeedIndexOut"];
export type FeedCampaignSummary = components["schemas"]["FeedCampaignSummary"];
export type StatsOut = components["schemas"]["StatsOut"];
export type OverviewOut = components["schemas"]["OverviewOut"];
export type ConfigDomainOut = components["schemas"]["ConfigDomainOut"];
export type ConfigListOut = components["schemas"]["ConfigListOut"];
export type ConfigDomain = ConfigDomainOut["domain"];

/** Mirrors the backend's `Literal["low", "moderate", "high"]` (see
 * `assess/drafter.py`) — not a named OpenAPI component (pydantic inlines
 * Literal fields), so declared once here for reuse across components. */
export type Confidence = "low" | "moderate" | "high";
export const CONFIDENCE_VALUES: Confidence[] = ["low", "moderate", "high"];

export class ApiError extends Error {
  readonly status: number;
  readonly errors: string[];

  constructor(status: number, errors: string[]) {
    super(errors.join("; "));
    this.name = "ApiError";
    this.status = status;
    this.errors = errors;
  }
}

interface FastApiValidationItem {
  loc?: unknown[];
  msg?: string;
}

function extractErrors(body: unknown): string[] {
  if (body && typeof body === "object" && "detail" in body) {
    const detail = (body as { detail: unknown }).detail;
    if (typeof detail === "string") {
      return [detail];
    }
    if (detail && typeof detail === "object" && "errors" in detail) {
      const errors = (detail as { errors: unknown }).errors;
      if (Array.isArray(errors)) {
        return errors.map(String);
      }
    }
    if (Array.isArray(detail)) {
      // FastAPI/pydantic's own schema-validation error array shape.
      return detail.map((item) => {
        const validationItem = item as FastApiValidationItem;
        const loc = Array.isArray(validationItem.loc) ? validationItem.loc.join(".") : "";
        return loc ? `${loc}: ${validationItem.msg ?? ""}` : String(validationItem.msg ?? item);
      });
    }
  }
  return ["An unexpected error occurred."];
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, {
    ...init,
    headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) },
  });
  if (!response.ok) {
    const body: unknown = await response.json().catch(() => null);
    throw new ApiError(response.status, extractErrors(body));
  }
  if (response.status === 204) {
    return undefined as T;
  }
  return (await response.json()) as T;
}

function qs(params: Record<string, string | number | boolean | undefined>): string {
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined && value !== "") {
      search.set(key, String(value));
    }
  }
  const str = search.toString();
  return str ? `?${str}` : "";
}

export const api = {
  listCampaigns(params?: { status?: string; min_size?: number; search?: string }) {
    return request<CampaignListResponse>(`/api/campaigns${qs(params ?? {})}`);
  },
  getCampaign(code: string) {
    return request<CampaignDetail>(`/api/campaigns/${encodeURIComponent(code)}`);
  },
  updateDisplayName(code: string, displayName: string | null) {
    return request<CampaignDetail>(`/api/campaigns/${encodeURIComponent(code)}/display_name`, {
      method: "PUT",
      body: JSON.stringify({ display_name: displayName }),
    });
  },
  getCampaignGraph(code: string) {
    return request<CampaignGraph>(`/api/campaigns/${encodeURIComponent(code)}/graph`);
  },
  explainIndicator(code: string, indicatorId: string) {
    return request<ExplainOut>(
      `/api/campaigns/${encodeURIComponent(code)}/explain/${encodeURIComponent(indicatorId)}`,
    );
  },
  getAssessment(code: string, version?: number) {
    return request<AssessmentOut>(
      `/api/campaigns/${encodeURIComponent(code)}/assessment${qs({ version })}`,
    );
  },
  listAssessmentVersions(code: string) {
    return request<AssessmentVersionSummary[]>(
      `/api/campaigns/${encodeURIComponent(code)}/assessment/versions`,
    );
  },
  diffAssessment(code: string, from: number, to: number) {
    return request<AssessmentDiffOut>(
      `/api/campaigns/${encodeURIComponent(code)}/assessment/diff${qs({ from, to })}`,
    );
  },
  createDraft(code: string, force = false) {
    return request<AssessmentOut>(`/api/campaigns/${encodeURIComponent(code)}/assessment/draft`, {
      method: "POST",
      body: JSON.stringify({ force }),
    });
  },
  editAssessment(code: string, version: number, draft: AssessmentDraft) {
    return request<AssessmentOut>(
      `/api/campaigns/${encodeURIComponent(code)}/assessment/${version}`,
      { method: "PUT", body: JSON.stringify(draft) },
    );
  },
  approveAssessment(
    code: string,
    version: number,
    notes: string,
    opts?: { reviewer?: string; force?: boolean },
  ) {
    return request<AssessmentOut>(
      `/api/campaigns/${encodeURIComponent(code)}/assessment/${version}/approve`,
      {
        method: "POST",
        body: JSON.stringify({ notes, reviewer: opts?.reviewer, force: opts?.force ?? false }),
      },
    );
  },
  rejectAssessment(code: string, version: number, notes: string, reviewer?: string) {
    return request<AssessmentOut>(
      `/api/campaigns/${encodeURIComponent(code)}/assessment/${version}/reject`,
      { method: "POST", body: JSON.stringify({ notes, reviewer }) },
    );
  },
  listAttackTechniques() {
    return request<AttackTechniquesOut>("/api/attack/techniques");
  },
  getReport(code: string) {
    return request<ReportMeta>(`/api/reports/${encodeURIComponent(code)}`);
  },
  getFeedIndex() {
    return request<FeedIndexOut>("/api/feed");
  },
  getStats() {
    return request<StatsOut>("/api/stats");
  },
  getOverview() {
    return request<OverviewOut>("/api/overview");
  },
  listConfig() {
    return request<ConfigListOut>("/api/config");
  },
  getConfig(domain: ConfigDomain) {
    return request<ConfigDomainOut>(`/api/config/${domain}`);
  },
  setConfig(domain: ConfigDomain, value: Record<string, unknown>) {
    return request<ConfigDomainOut>(`/api/config/${domain}`, {
      method: "PUT",
      body: JSON.stringify(value),
    });
  },
  resetConfig(domain: ConfigDomain) {
    return request<ConfigDomainOut>(`/api/config/${domain}/reset`, { method: "POST" });
  },
};
